"""Reading lock files semantically, and the package-level actions (#306)."""

from __future__ import annotations

from precondition_library.bench import lock_actions as la

CARGO = """
# This file is automatically @generated by Cargo.
version = 3

[[package]]
name = "libc"
version = "0.2.161"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "abc"

[[package]]
name = "syn"
version = "1.0.109"

[[package]]
name = "syn"
version = "2.0.77"
"""

POETRY = """
[[package]]
name = "requests"
version = "2.31.0"
description = "HTTP"

[[package]]
name = "urllib3"
version = "2.0.7"

[metadata]
lock-version = "2.0"
"""

YARN = """# THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.
# yarn lockfile v1


"@babel/code-frame@^7.0.0", "@babel/code-frame@^7.10.4":
  version "7.12.13"
  resolved "https://registry.yarnpkg.com/@babel/code-frame/-/code-frame-7.12.13.tgz"
  dependencies:
    "@babel/highlight" "^7.12.13"

abab@^2.0.0:
  version "2.0.5"

lodash@^4.17.15, lodash@^4.17.21:
  version "4.17.21"
"""


def test_cargo_reads_every_package_and_version_whatever_the_format() -> None:
    assert la.packages("Cargo.lock", CARGO) == {
        ("libc", "0.2.161"),
        ("syn", "1.0.109"),
        ("syn", "2.0.77"),
    }
    reformatted = CARGO.replace('checksum = "abc"\n', "").replace("version = 3\n", "version = 4\n")
    assert la.packages("Cargo.lock", reformatted) == la.packages("Cargo.lock", CARGO)


def test_poetry_reads_packages_not_metadata() -> None:
    assert la.packages("poetry.lock", POETRY) == {("requests", "2.31.0"), ("urllib3", "2.0.7")}


def test_yarn_reads_scoped_names_and_keys_with_several_ranges() -> None:
    assert la.packages("web/yarn.lock", YARN) == {
        ("@babel/code-frame", "7.12.13"),
        ("abab", "2.0.5"),
        ("lodash", "4.17.21"),
    }


def test_a_file_with_conflict_markers_or_of_another_kind_is_unread() -> None:
    assert la.packages("Cargo.lock", "<<<<<<< HEAD\n[[package]]\n") is None
    assert la.packages("package-lock.json", "{}") is None


def test_three_way_keeps_both_sides_changes_package_by_package() -> None:
    base = {("a", "1.0.0"), ("b", "1.0.0"), ("c", "1.0.0")}
    local = {("a", "1.0.0"), ("b", "1.1.0"), ("c", "1.0.0"), ("new-local", "0.1.0")}
    upstream = {("a", "1.0.0"), ("b", "1.0.0"), ("new-up", "2.0.0")}  # upstream dropped c
    assert la.three_way(base, local, upstream) == {
        ("a", "1.0.0"),
        ("b", "1.1.0"),
        ("new-local", "0.1.0"),
        ("new-up", "2.0.0"),
    }


def test_unify_keeps_the_highest_compatible_version_only() -> None:
    both_bumped = {("libc", "0.2.155"), ("libc", "0.2.161"), ("syn", "1.0.9"), ("syn", "2.0.1")}
    assert la.unify("Cargo.lock", both_bumped) == {
        ("libc", "0.2.161"),
        ("syn", "1.0.9"),
        ("syn", "2.0.1"),
    }
    assert la.unify("Cargo.lock", {("x", "1.2.0"), ("x", "1.10.0")}) == {("x", "1.10.0")}
    assert la.unify("poetry.lock", {("a", "1.0"), ("a", "2.0")}) == {("a", "2.0")}


def test_drift_tolerance_forgives_only_packages_new_to_the_merge() -> None:
    merged = {("old", "1.0.0"), ("new", "1.0.0")}
    assert la.same_but_new({("old", "1.0.0"), ("new", "1.4.0")}, merged, before={"old"})
    assert not la.same_but_new({("old", "1.1.0"), ("new", "1.0.0")}, merged, before={"old"})
    assert not la.same_but_new({("old", "1.0.0")}, merged, before={"old"})


def test_a_case_is_reproduced_only_if_every_lock_file_is() -> None:
    def result(action: str, ok: bool) -> la.ActionResult:
        return la.ActionResult(action=action, reproduces=ok, reproduces_but_new=ok, jaccard=1.0)

    first = [result(a, a == "three_way") for a in la.ACTIONS]
    second = [result(a, a in ("three_way", "take_local")) for a in la.ACTIONS]
    summary = la.summarise([first, second])
    assert summary["three_way"] and not summary["take_local"]
